INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'4894', E'2426', E'attendance-report', E'Attendance report: 2026-10-26 to 2026-10-27', E'SMRITHI K', E'smrithik', E'SMIB-EMP-26f786a8-f668-447c-996c-b5e875867e13', E'intern', E'PCB Design Intern', E'MIB08', E'PCB Designs & Fabrication Team', E'8610492864', '{"fromDate": "2026-10-26", "toDate": "2026-10-27", "remarks": "We have completed the requirements analysis for both the single-phase and three-phase motor starter applications and decided on a modular architecture. This approach uses a single universal control PCB, while heavy-duty components like SSRs and heat sinks are mounted externally to safely manage thermal differences. To streamline development, we divided the schematic into four functional blocks: Power Supply, MCU & User Interface, Sensing, and SSR Isolation. We selected the STM32G474 microcontroller for its accurate analog monitoring capabilities, and chose Current Transformers (CT) over Hall-effect sensors to keep dangerous high-current traces off the board. We are now proceeding with drafting the schematics in Altium Designer to meet the upcoming submission deadline.", "daysRecorded": 2, "attendance": [{"id": "01b5ec32-4811-40cb-a11b-32b4530c5631", "userId": "SMIB-EMP-26f786a8-f668-447c-996c-b5e875867e13", "username": "smrithik", "fullName": "SMRITHI K", "employeeId": "MIB08", "date": "2026-10-27", "checkIn": "2026-10-27T03:14:46.993Z", "checkOut": "2026-10-27T12:21:41.361Z"}, {"id": "a2a6b5c9-6e69-4501-9ef2-cc416641012d", "userId": "SMIB-EMP-26f786a8-f668-447c-996c-b5e875867e13", "username": "smrithik", "fullName": "SMRITHI K", "employeeId": "MIB08", "date": "2026-10-26", "checkIn": "2026-10-26T02:57:54.171Z"}], "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-30T09:13:42.634Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-30T09:12:53.898Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-30T06:06:03.176Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-30T03:32:47.069Z"}]}'::jsonb, E'We have completed the requirements analysis for both the single-phase and three-phase motor starter applications and decided on a modular architecture. This approach uses a single universal control PCB, while heavy-duty components like SSRs and heat sinks are mounted externally to safely manage thermal differences. To streamline development, we divided the schematic into four functional blocks: Power Supply, MCU & User Interface, Sensing, and SSR Isolation. We selected the STM32G474 microcontroller for its accurate analog monitoring capabilities, and chose Current Transformers (CT) over Hall-effect sensors to keep dangerous high-current traces off the board. We are now proceeding with drafting the schematics in Altium Designer to meet the upcoming submission deadline.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-27T12:21:57.291Z', E'2026-10-30T09:13:42.635Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'5124', E'6000', E'attendance-report', E'Attendance report: 2026-10-27 to 2026-10-27', E'RITHANYA D', E'rithanyad', E'SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb', E'intern', E'PCB Design Intern', E'MIB09', E'PCB Designs & Fabrication Team', E'9384304331', '{"fromDate": "2026-10-27", "toDate": "2026-10-27", "remarks": "Today, the project was divided into four functional blocks to organize the system design and component selection systematically:\n\nPower Supply Unit (PSU)\n\nCore Sensing and Protection\n\nIsolation and SSR Switching\n\nUser Interface and Logic\n\nFor the Core Sensing and Protection block, the STM32G474 microcontroller was shortlisted based on its high-resolution ADC, integrated comparators, and fast fault-detection capabilities.\n\nResearch was initiated to identify suitable voltage and current sensing components compatible with the selected microcontroller. The associated signal-conditioning circuits and protection requirements are also being evaluated.\n\nFor the Power Supply Unit, the requirements for both single-phase and three-phase operation were identified as key factors to be analysed before finalizing the circuit design and component selection.\n\nThe component selection process is being organized block-wise to simplify design decisions, identify component dependencies, and support systematic prototype development.\n\nNext Steps\n\nFinalize suitable voltage and current sensing components.\n\nAnalyse signal-conditioning and input-protection requirements.\n\nEvaluate PSU requirements for single-phase and three-phase operation.\n\nSelect suitable isolation and SSR switching components.\n\nPrepare the preliminary circuit design and verify component compatibility.\n\nCurrent Status\n\nThe project is in the functional block planning and component research phase. The microcontroller has been shortlisted, and further component evaluation is required before finalizing the circuit design and proceeding to prototyping.", "daysRecorded": 1, "attendance": [{"id": "978dd5df-fcf5-461a-909c-636d99660ac0", "userId": "SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb", "username": "rithanyad", "fullName": "RITHANYA D", "employeeId": "MIB09", "date": "2026-10-27", "checkIn": "2026-10-27T03:16:18.362Z", "checkOut": "2026-10-27T12:10:04.089Z"}], "approvalChain": ["vishnuu", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "guideId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "guideUsername": "vishnuu", "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-28T03:10:50.571Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-28T03:10:05.263Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-27T12:32:39.251Z"}, {"by": "vishnuu", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-27T12:32:20.689Z"}]}'::jsonb, E'Today, the project was divided into four functional blocks to organize the system design and component selection systematically:\n\nPower Supply Unit (PSU)\n\nCore Sensing and Protection\n\nIsolation and SSR Switching\n\nUser Interface and Logic\n\nFor the Core Sensing and Protection block, the STM32G474 microcontroller was shortlisted based on its high-resolution ADC, integrated comparators, and fast fault-detection capabilities.\n\nResearch was initiated to identify suitable voltage and current sensing components compatible with the selected microcontroller. The associated signal-conditioning circuits and protection requirements are also being evaluated.\n\nFor the Power Supply Unit, the requirements for both single-phase and three-phase operation were identified as key factors to be analysed before finalizing the circuit design and component selection.\n\nThe component selection process is being organized block-wise to simplify design decisions, identify component dependencies, and support systematic prototype development.\n\nNext Steps\n\nFinalize suitable voltage and current sensing components.\n\nAnalyse signal-conditioning and input-protection requirements.\n\nEvaluate PSU requirements for single-phase and three-phase operation.\n\nSelect suitable isolation and SSR switching components.\n\nPrepare the preliminary circuit design and verify component compatibility.\n\nCurrent Status\n\nThe project is in the functional block planning and component research phase. The microcontroller has been shortlisted, and further component evaluation is required before finalizing the circuit design and proceeding to prototyping.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-27T12:11:11.517Z', E'2026-10-28T03:10:50.571Z') ON CONFLICT ("id") DO NOTHING;
